package com.yuegang.zhihui.product.api;import com.yuegang.zhihui.common.core.ApiResponse;import com.yuegang.zhihui.common.web.TraceIdResolver;import com.yuegang.zhihui.product.application.CatalogService;import com.yuegang.zhihui.product.security.ProductAdminVerifier;import jakarta.servlet.http.HttpServletRequest;import jakarta.validation.Valid;import java.util.List;import org.springframework.web.bind.annotation.*;@RestController public final class CatalogController{private final CatalogService service;private final ProductAdminVerifier admin;public CatalogController(CatalogService s,ProductAdminVerifier a){service=s;admin=a;}@GetMapping("/api/v1/product-categories")ApiResponse<List<CategoryView>>categories(HttpServletRequest r){return ok(service.categories(true),r);}@GetMapping("/api/v1/product-brands")ApiResponse<List<BrandView>>brands(HttpServletRequest r){return ok(service.brands(true),r);}@GetMapping("/api/v1/products/{sku}/trace-events")ApiResponse<List<TraceEventView>>trace(@PathVariable String sku,HttpServletRequest r){return ok(service.trace(sku),r);}@PostMapping("/api/v1/admin/product-categories")ApiResponse<CategoryView>category(@Valid @RequestBody SaveCategoryRequest b,HttpServletRequest r){admin.verify(r);return ok(service.createCategory(b),r);}@PostMapping("/api/v1/admin/product-brands")ApiResponse<BrandView>brand(@Valid @RequestBody SaveBrandRequest b,HttpServletRequest r){admin.verify(r);return ok(service.createBrand(b),r);}@PostMapping("/api/v1/admin/products/{sku}/trace-events")ApiResponse<TraceEventView>trace(@PathVariable String sku,@Valid @RequestBody TraceEventRequest b,HttpServletRequest r){admin.verify(r);return ok(service.addTrace(sku,b),r);}private static<T>ApiResponse<T>ok(T x,HttpServletRequest r){return ApiResponse.success(x,TraceIdResolver.resolve(r));}}
